import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Alchemy","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/alchemy.md","filePath":"en/guide/professions/alchemy.md"}'),s={name:"en/guide/professions/alchemy.md"};function n(o,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="alchemy" tabindex="-1">Alchemy <a class="header-anchor" href="#alchemy" aria-label="Permalink to &quot;Alchemy&quot;">​</a></h1><p><strong>Status:</strong> Proposed · New design not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Alchemy turns simplified material reactions into useful preparations.</li><li>Smoke, toxins, medical mixtures and reagents give it field and economic value.</li><li>Skill improves execution; techniques and experimentation expand knowledge.</li></ul><p>Alchemy turns simplified reactions into useful preparations. It should reward experimentation without becoming a chemistry simulator.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Proposed role</th></tr></thead><tbody><tr><td>Processes</td><td>Crush, dissolve, heat, distill, separate, combine</td></tr><tr><td>Products</td><td>Oils, powders, salves, inks, solvents, preservatives, draughts</td></tr><tr><td>Field support</td><td>Smoke, adhesives, volatile mixtures, toxins, medical preparations</td></tr><tr><td>Journal</td><td>Observations develop into understood formulations</td></tr></tbody></table><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Factor</th><th>Why it matters</th></tr></thead><tbody><tr><td>Skill</td><td>Broadens work and consistency</td></tr><tr><td>Techniques</td><td>Distillation and Toxicology open specific paths</td></tr><tr><td>Materials</td><td>Quality, purity and stability affect the result</td></tr><tr><td>Knowledge</td><td>A copied recipe does not reproduce someone else&#39;s mastery</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A future analgesic might suppress pain penalties without healing the underlying trauma. Medical interactions and counterplay remain unresolved.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/tinkering.html">Tinkering payloads</a> · <a href="/Syrolands-Public/en/guide/professions/tailoring.html">Tailoring treatments</a> · <a href="/Syrolands-Public/en/guide/magic/spellbooks-scrolls-and-reagents.html">Physical magic materials</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Shared production</a> · <a href="/Syrolands-Public/en/game-design/professions/alchemy.html">Full specification</a></p><p>Reagent processing may support magic and Inscription; recipes are undecided and carried materials retain loot risk.</p><p><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="progression-and-related-crafts"></span><span id="magic-materials"></span></p>',15)])])}const u=a(s,[["render",n]]);export{m as __pageData,u as default};
